    pairs = []
    for key, value in params.items():
        if value is None:
            continue
        values = value if isinstance(value, (list, tuple)) else [value]
        for item in values:
            pairs.append(_encode(key) + "=" + _encode(item))
    return "&".join(pairs)


def _encode(value) -> str:
    if isinstance(value, bool):
        text = "true" if value else "false"
    else:
        text = str(value)
    # quote() leaves only ASCII letters, digits and "-._~" (plus ``safe``)
    # unescaped, uses uppercase hex, and encodes spaces as %20.
    return quote(text, safe="", encoding="utf-8")
